import{I as s,o as l,c as t,b6 as o,J as p,w as d,j as a,a as i}from"./chunks/framework.BUXTSoD9.js";const h=JSON.parse('{"title":"Modelo Double Diamond: primero haz lo correcto, luego hazlo bien","description":"Comprende las cuatro etapas de Discover, Define, Develop, Deliver para evitar crear prototipos antes de entender bien el problema.","frontmatter":{"title":"Modelo Double Diamond: primero haz lo correcto, luego hazlo bien","description":"Comprende las cuatro etapas de Discover, Define, Develop, Deliver para evitar crear prototipos antes de entender bien el problema."},"headers":[],"relativePath":"es-es/stage-1/appendix-double-diamond/index.md","filePath":"es-es/stage-1/appendix-double-diamond/index.md"}'),c={name:"es-es/stage-1/appendix-double-diamond/index.md"},g=Object.assign(c,{setup(u){const n="Aproximadamente <strong>1.5 horas</strong>";return(m,e)=>{const r=s("ChapterIntroduction");return l(),t("div",null,[e[1]||(e[1]=o('<h1 id="modelo-double-diamond-primero-haz-lo-correcto-luego-hazlo-bien" tabindex="-1">Modelo Double Diamond: primero haz lo correcto, luego hazlo bien <a class="header-anchor" href="#modelo-double-diamond-primero-haz-lo-correcto-luego-hazlo-bien" aria-label="Permalink to “Modelo Double Diamond: primero haz lo correcto, luego hazlo bien”">​</a></h1><p><a id="top-dd"></a></p><h2 id="resumen-del-capitulo" tabindex="-1">Resumen del capitulo <a class="header-anchor" href="#resumen-del-capitulo" aria-label="Permalink to “Resumen del capitulo”">​</a></h2>',3)),p(r,{duration:n,tags:["Double Diamond","Pensamiento de diseno","Analisis de necesidades","Diseno de soluciones"],coreOutput:"1 definicion de problema mas clara y 1 punto de entrada de validacion mas razonable",expectedOutput:"Dejar de precipitarse a dibujar prototipos, sabiendo primero pensar claramente en el problema y luego comparar soluciones"},{default:d(()=>[...e[0]||(e[0]=[a("p",null,'Muchas personas, la primera vez que hacen un producto, caen en la trampa mas facil: no es que "no se esfuercen lo suficiente", sino que entran demasiado rapido en la solucion.',-1),a("p",null,"Apenas les viene una direccion a la mente, ya estan pensando en como dibujar la pagina, donde poner los botones, si conectar IA, si hacer login y registro, con que herramienta hacer el prototipo. Despues de un rato de trabajo, descubren que el problema mas fundamental no se ha pensado claramente: el usuario realmente tiene este punto de dolor? Vale la pena resolver este problema ahora? Crees que estas avanzando en el proyecto, pero en realidad solo estas acelerando en la direccion equivocada.",-1),a("p",null,"El modelo Double Diamond existe precisamente para evitar esta situacion.",-1),a("p",null,[i("Su recordatorio mas valioso es: "),a("strong",null,'"hacer lo correcto" y "hacerlo bien" son dos etapas completamente diferentes.'),i(" Si aun no has aclarado el problema y te precipitas a hacer prototipos, normalmente solo haras la direccion equivocada mas completa.")],-1)])]),_:1}),e[2]||(e[2]=o(`<div class="info custom-block"><p class="custom-block-title">SOP minimo</p><p><strong>Objetivo</strong>: Despues de leer, sabras mejor cuando hacer productos, cuando pensar primero en el problema y cuando empezar a pensar en soluciones y prototipos, evitando precipitarte en la direccion equivocada desde el principio.</p><p><strong>Accion</strong>: Sigue los cuatro pasos <code>Discover -&gt; Define -&gt; Develop -&gt; Deliver</code>, haciendo solo lo que corresponde a la etapa actual en cada paso.</p><p><strong>Resultado</strong>: Obtendras una definicion de problema mas clara, varias soluciones comparables y una version minima verificable.</p><p><strong>Enlaces rapidos</strong>: <a href="#dd-what">Que es el Double Diamond</a> · <a href="#dd-first">Primer diamante</a> · <a href="#dd-ai">Como te ayuda la IA</a></p></div><h2 id="aprenderas-lo-siguiente" tabindex="-1">Aprenderas lo siguiente <a class="header-anchor" href="#aprenderas-lo-siguiente" aria-label="Permalink to “Aprenderas lo siguiente”">​</a></h2><ol><li>Que es el modelo Double Diamond, y por que es adecuado para personas sin experiencia al hacer productos</li><li>Que hacen las cuatro etapas Discover, Define, Develop y Deliver respectivamente</li><li>Como distinguir entre &quot;ahora debo seguir divergiendo&quot; y &quot;ahora debo empezar a converger&quot;</li><li>Como usar el modelo Double Diamond en productos de IA, diseno de prototipos y validacion de necesidades</li></ol><p><a id="dd-what"></a></p><h2 id="_1-que-es-exactamente-el-modelo-double-diamond" tabindex="-1"><a href="#top-dd">1. Que es exactamente el modelo Double Diamond</a> <a class="header-anchor" href="#_1-que-es-exactamente-el-modelo-double-diamond" aria-label="Permalink to “1. Que es exactamente el modelo Double Diamond”">​</a></h2><p>El modelo Double Diamond es un marco clasico de proceso de diseno promovido por el <strong>Design Council</strong> del Reino Unido. Representa un proceso completo de diseno e innovacion como dos formas de diamante consecutivas.</p><p>La razon de ser &quot;diamantes&quot; es que cada diamante contiene dos acciones opuestas pero igualmente importantes:</p><ul><li><strong>Divergencia</strong>: primero abrir el campo de vision, ver mas posibilidades</li><li><strong>Convergencia</strong>: luego reducir el alcance, tomar decisiones y priorizar</li></ul><p>Todo el proceso tiene cuatro pasos:</p><ol><li><strong>Discover</strong>: entender ampliamente a los usuarios, problemas, entorno y mercado</li><li><strong>Define</strong>: extraer de la gran cantidad de informacion el problema central que realmente vale la pena resolver</li><li><strong>Develop</strong>: explorar multiples soluciones alrededor del problema central</li><li><strong>Deliver</strong>: filtrar, prototipar, probar y entregar la solucion mas adecuada</li></ol><p>Si comprimes estos cuatro pasos en una frase facil de recordar, seria:</p><ul><li><strong>Primer diamante</strong>: primero aclarar que problema resolver exactamente</li><li><strong>Segundo diamante</strong>: luego decidir con que solucion resolverlo</li></ul><p>Que es exactamente lo que dijiste muy bien:</p><ul><li><strong>Primer diamante: hacer lo correcto</strong></li><li><strong>Segundo diamante: hacerlo bien</strong></li></ul><h2 id="_2-por-que-el-modelo-double-diamond-es-especialmente-adecuado-para-principiantes" tabindex="-1">2. Por que el modelo Double Diamond es especialmente adecuado para principiantes <a class="header-anchor" href="#_2-por-que-el-modelo-double-diamond-es-especialmente-adecuado-para-principiantes" aria-label="Permalink to “2. Por que el modelo Double Diamond es especialmente adecuado para principiantes”">​</a></h2><p>El ritmo mas comun de los principiantes al hacer productos suele ser:</p><ul><li>Se les ocurre una idea</li><li>Les parece que esta direccion es genial</li><li>Empiezan inmediatamente a dibujar prototipos</li><li>Haciendo y haciendo, descubren que las funciones son cada vez mas</li><li>Al final no saben que problema estan resolviendo exactamente</li></ul><p>El valor del modelo Double Diamond no esta en complicar el proceso, sino en <strong>obligarte a separar &quot;entender el problema&quot; y &quot;disenar la solucion&quot;.</strong></p><p>Esto suena muy comun, pero en realidad es muy importante. Porque muchos productos fracasados no es que la ejecucion no fuera seria, sino:</p><ul><li>Eligieron el problema equivocado</li><li>Malentendieron al usuario</li><li>Se bloquearon demasiado pronto en una solucion</li><li>Gastaron mucho tiempo en pulir detalles sin validar la direccion</li></ul><p>El modelo Double Diamond te esta recordando constantemente:</p><ul><li>No porque una idea te parezca facil, asumas que el problema ya esta confirmado</li><li>No porque una solucion pueda implementarse, asumas que vale la pena hacerla</li><li>No porque un prototipo parezca completo, asumas que los usuarios realmente lo necesitaran</li></ul><p><a id="dd-first"></a></p><h2 id="_3-primer-diamante-hacer-lo-correcto" tabindex="-1"><a href="#top-dd">3. Primer diamante: hacer lo correcto</a> <a class="header-anchor" href="#_3-primer-diamante-hacer-lo-correcto" aria-label="Permalink to “3. Primer diamante: hacer lo correcto”">​</a></h2><p>El primer diamante se centra en <strong>el problema en si</strong>, no en la solucion.</p><p>Puedes entenderlo como una frase: <strong>no te precipites, primero averigua si realmente vale la pena hacerlo.</strong></p><h3 id="_3-1-discover-primero-abre-el-espacio-del-problema" tabindex="-1">3.1 Discover: primero abre el espacio del problema <a class="header-anchor" href="#_3-1-discover-primero-abre-el-espacio-del-problema" aria-label="Permalink to “3.1 Discover: primero abre el espacio del problema”">​</a></h3><p>La tarea central de la fase Discover es <strong>investigar ampliamente, no llegar rapido a conclusiones.</strong></p><p>Lo que normalmente se hace en este paso incluye:</p><ul><li>Ver como los usuarios actuan en escenarios reales</li><li>Entrevistar a usuarios potenciales, entender cuando fue la ultima vez que encontraron el problema</li><li>Observar como se las arreglan actualmente</li><li>Ver como manejan la competencia y las soluciones alternativas</li><li>Recoger informacion de mercado, procesos, restricciones y relaciones aguas arriba/aguas abajo</li></ul><p>Muchas personas confunden Discover con &quot;ver mas informacion&quot;. Pero lo mas critico es: <strong>tienes que entender a las personas y los escenarios, no solo buscar un monton de informacion.</strong></p><p>Por ejemplo, si quieres hacer una herramienta de &quot;IA que ayuda a organizar actas de reuniones&quot;, en la fase Discover deberias prestar mas atencion a:</p><ul><li>Despues de la reunion, donde duele mas exactamente al usuario</li><li>Es dificil tomar notas, organizarlas o sincronizarlas</li><li>Ahora escriben ellos mismos, le piden al becario, escuchan la grabacion, o simplemente no organizan</li><li>Que escenarios de reunion necesitan mas actas y cuales no las necesitan en absoluto</li></ul><p>El objetivo mas importante de este paso no es llegar a una respuesta, sino <strong>no asumir demasiado pronto que ya conoces la respuesta.</strong></p><h3 id="_3-2-define-extraer-el-problema-central-de-un-monton-de-informacion" tabindex="-1">3.2 Define: extraer el problema central de un monton de informacion <a class="header-anchor" href="#_3-2-define-extraer-el-problema-central-de-un-monton-de-informacion" aria-label="Permalink to “3.2 Define: extraer el problema central de un monton de informacion”">​</a></h3><p>Si Discover abre el campo de vision, Define empieza a cerrarlo.</p><p>Lo que hay que hacer en la fase Define no es mantener todas las observaciones, sino preguntar:</p><ul><li>Cual es el problema que realmente merece la pena resolver primero</li><li>Que problema aparece con mas frecuencia, es el mas doloroso y el mas valioso</li><li>En que escenario unico debemos centrarnos en la primera version</li></ul><p>El nucleo de este paso es converger un tema amplio en una definicion de problema clara.</p><p>Por ejemplo, al principio dices:</p><blockquote><p>Quiero hacer una herramienta con IA para mejorar la eficiencia de las reuniones.</p></blockquote><p>En la fase Define, una mejor expresion podria ser:</p><blockquote><p>Primero resolvamos el problema de que los equipos de proyecto, despues de reuniones de colaboracion de 30 a 60 minutos, no pueden producir en 10 minutos un acta con tareas pendientes, responsables y fechas limite.</p></blockquote><p>En este punto el problema empieza a aclararse:</p><ul><li>Quien es el usuario</li><li>Cual es el escenario</li><li>Cual es el punto de bloqueo</li><li>Cual es el criterio de exito</li></ul><p>La esencia de Define es <strong>converger de &quot;hay muchos problemas&quot; a &quot;que problema resolver primero esta vez&quot;.</strong></p><h2 id="_4-segundo-diamante-hacerlo-bien" tabindex="-1">4. Segundo diamante: hacerlo bien <a class="header-anchor" href="#_4-segundo-diamante-hacerlo-bien" aria-label="Permalink to “4. Segundo diamante: hacerlo bien”">​</a></h2><p>Cuando completas el primer diamante, solo entonces es realmente apropiado entrar en el segundo. Porque ahora no estas resolviendo una direccion vaga, sino un problema concreto que ha sido convergido.</p><h3 id="_4-1-develop-diverge-soluciones-alrededor-del-problema-central" tabindex="-1">4.1 Develop: diverge soluciones alrededor del problema central <a class="header-anchor" href="#_4-1-develop-diverge-soluciones-alrededor-del-problema-central" aria-label="Permalink to “4.1 Develop: diverge soluciones alrededor del problema central”">​</a></h3><p>El foco de la fase Develop es <strong>explorar multiples soluciones posibles alrededor del mismo problema.</strong></p><p>Nota, la divergencia aqui es diferente de la fase Discover.</p><ul><li>La divergencia de Discover explora el espacio de problemas</li><li>La divergencia de Develop explora el espacio de soluciones</li></ul><p>Por ejemplo, en el caso de las actas de reuniones, al llegar a la fase Develop, puedes empezar a pensar:</p><ul><li>Hacer una herramienta web o un plugin de reuniones</li><li>Procesar despues de subir la grabacion o registrar en tiempo real</li><li>Solo hacer resumenes o enfocarse en extraer tareas pendientes</li><li>Enfatizar la eficiencia individual o la sincronizacion del equipo</li><li>Dar al usuario libertad de edicion o producir directamente plantillas estructuradas</li></ul><p>Este paso es ideal para brainstorming y para abrir las soluciones con el equipo.</p><p>Pero hay un requisito previo: <strong>todas las soluciones deben servir al mismo problema ya definido.</strong><br> Si el problema no esta claramente definido, Develop facilmente se convierte de nuevo en funciones volando en todas direcciones.</p><h3 id="_4-2-deliver-elegir-la-solucion-hacer-prototipos-probar-y-entregar" tabindex="-1">4.2 Deliver: elegir la solucion, hacer prototipos, probar y entregar <a class="header-anchor" href="#_4-2-deliver-elegir-la-solucion-hacer-prototipos-probar-y-entregar" aria-label="Permalink to “4.2 Deliver: elegir la solucion, hacer prototipos, probar y entregar”">​</a></h3><p>La fase Deliver es la fase de convergencia del segundo diamante.</p><p>Lo que debes hacer aqui no es seguir pensando mas, sino empezar a juzgar:</p><ul><li>Que solucion es mas adecuada para la etapa actual</li><li>Que version es la mas pequena pero mas util</li><li>Que funciones deben hacerse primero y cuales pueden esperar</li><li>Como hacer prototipos, pruebas y validacion a pequena escala</li></ul><p>Muchas personas piensan que Deliver equivale a &quot;lanzamiento&quot;. Pero su significado mas preciso es: <strong>convertir una solucion en algo que se pueda probar, verificar e iterar.</strong></p><p>Puede ser:</p><ul><li>Un diagrama de flujo de baja fidelidad</li><li>Un prototipo en Figma</li><li>Un MVP funcional</li><li>Una prueba de usuario a pequena escala</li><li>Una version iterada despues de retroalimentacion real</li></ul><p>El punto de Deliver no es &quot;entrega perfecta&quot;, sino <strong>poner la solucion en un entorno real para verificarla lo antes posible.</strong></p><h2 id="_5-una-tabla-de-comparacion-facil-de-recordar" tabindex="-1">5. Una tabla de comparacion facil de recordar <a class="header-anchor" href="#_5-una-tabla-de-comparacion-facil-de-recordar" aria-label="Permalink to “5. Una tabla de comparacion facil de recordar”">​</a></h2><p>Si siempre te confundes con las cuatro etapas, puedes recordar directamente esta version:</p><table tabindex="0"><thead><tr><th>Etapa</th><th>Que estas haciendo</th><th>Palabras clave</th><th>Productos comunes</th></tr></thead><tbody><tr><td>Discover</td><td>Entender el problema</td><td>Investigacion, observacion, entrevistas, recopilar informacion</td><td>Insights de usuarios, notas de escenario, lista de problemas</td></tr><tr><td>Define</td><td>Definir el problema</td><td>Extraer, enfocar, priorizar, reescribir el problema</td><td>Definicion del problema, prioridades, punto de entrada MVP</td></tr><tr><td>Develop</td><td>Explorar soluciones</td><td>Brainstorming, comparacion, cocreacion, conceptos de prototipo</td><td>Lista de soluciones, bocetos de flujo, direccion del prototipo</td></tr><tr><td>Deliver</td><td>Verificar soluciones</td><td>Prototipos, pruebas, iteracion, entrega</td><td>Prototipos, retroalimentacion de pruebas, version optimizada</td></tr></tbody></table><p>Comprimiendolo aun mas:</p><ul><li><strong>Discover / Define</strong>: resolver &quot;hacer lo correcto&quot;</li><li><strong>Develop / Deliver</strong>: resolver &quot;hacerlo bien&quot;</li></ul><h2 id="_6-los-errores-mas-comunes-con-el-modelo-double-diamond" tabindex="-1">6. Los errores mas comunes con el modelo Double Diamond <a class="header-anchor" href="#_6-los-errores-mas-comunes-con-el-modelo-double-diamond" aria-label="Permalink to “6. Los errores mas comunes con el modelo Double Diamond”">​</a></h2><h3 id="_6-1-pasar-directamente-a-deliver-sin-discover" tabindex="-1">6.1 Pasar directamente a Deliver sin Discover <a class="header-anchor" href="#_6-1-pasar-directamente-a-deliver-sin-discover" aria-label="Permalink to “6.1 Pasar directamente a Deliver sin Discover”">​</a></h3><p>Este es el mas comun. Muchas personas apenas tienen una idea y ya estan dibujando prototipos, escribiendo PRDs, conectando modelos, haciendo paginas.</p><p>El problema no es que no trabajes en serio, sino que puede que ni siquiera hayas confirmado si el problema vale la pena resolver.</p><h3 id="_6-2-discover-mucho-tiempo-pero-nunca-llegar-a-define" tabindex="-1">6.2 Discover mucho tiempo, pero nunca llegar a Define <a class="header-anchor" href="#_6-2-discover-mucho-tiempo-pero-nunca-llegar-a-define" aria-label="Permalink to “6.2 Discover mucho tiempo, pero nunca llegar a Define”">​</a></h3><p>Otro extremo es investigar continuamente, leer informacion constantemente, hacer entrevistas sin parar, pero sin atreverse a converger.</p><p>El Double Diamond no es para que diverjas infinitamente, sino para recordarte: despues de la divergencia debes entrar en la evaluacion y priorizacion.</p><h3 id="_6-3-despues-de-define-cambiar-el-problema-a-escondidas" tabindex="-1">6.3 Despues de Define, cambiar el problema a escondidas <a class="header-anchor" href="#_6-3-despues-de-define-cambiar-el-problema-a-escondidas" aria-label="Permalink to “6.3 Despues de Define, cambiar el problema a escondidas”">​</a></h3><p>Muchos equipos, al llegar a Develop, modifican la definicion del problema para adaptarse a una solucion que es mas facil de implementar.</p><p>Esto es peligroso. Porque puede que no estes resolviendo el problema, sino buscando justificaciones para la solucion que te gusta.</p><h3 id="_6-4-confundir-deliver-con-lanzamiento-completo" tabindex="-1">6.4 Confundir Deliver con &quot;lanzamiento completo&quot; <a class="header-anchor" href="#_6-4-confundir-deliver-con-lanzamiento-completo" aria-label="Permalink to “6.4 Confundir Deliver con &quot;lanzamiento completo&quot;”">​</a></h3><p>Deliver no significa que debas completar todo el producto para considerar que ha terminado. Muchas veces, un prototipo que se puede probar o una ronda de pruebas con usuarios reales ya es un buen deliver.</p><h2 id="_7-como-usar-el-modelo-double-diamond-en-productos-de-ia" tabindex="-1">7. Como usar el modelo Double Diamond en productos de IA <a class="header-anchor" href="#_7-como-usar-el-modelo-double-diamond-en-productos-de-ia" aria-label="Permalink to “7. Como usar el modelo Double Diamond en productos de IA”">​</a></h2><p>Los productos de IA son especialmente propensos a caer en la trampa de &quot;las capacidades primero&quot;, porque las capacidades del modelo parecen demasiado atractivas. Querras pensar directamente en:</p><ul><li>Deberia conectar multimodalidad?</li><li>Deberia hacer un Agent?</li><li>Deberia anadir workflows?</li><li>Deberia conectar voz, imagen, busqueda en la web?</li></ul><p>Pero el modelo Double Diamond te obliga a preguntar primero:</p><ul><li>En que paso exactamente el usuario esta bloqueado</li><li>Este bloqueo requiere SI o SI IA?</li><li>Sin IA, cual es exactamente la mayor debilidad del metodo actual</li><li>Despues de anadir IA, cual es el progreso mas importante</li></ul><p>Esto te ayuda a evitar una situacion comun: <strong>capacidades fuertes, valor debil.</strong></p><p>Una secuencia practica es:</p><ol><li>En la fase Discover, observar como los usuarios manejan las tareas actualmente</li><li>En la fase Define, escribir el escenario mas doloroso como una definicion de problema clara</li><li>En la fase Develop, comparar que capacidades de IA sirven mejor a este problema</li><li>En la fase Deliver, hacer una version minima para que usuarios reales la prueben</li></ol><h2 id="_8-una-plantilla-double-diamond-que-puedes-usar-directamente" tabindex="-1">8. Una plantilla Double Diamond que puedes usar directamente <a class="header-anchor" href="#_8-una-plantilla-double-diamond-que-puedes-usar-directamente" aria-label="Permalink to “8. Una plantilla Double Diamond que puedes usar directamente”">​</a></h2><p>Si estas haciendo tu propio producto, puedes seguir esta secuencia:</p><h3 id="discover" tabindex="-1">Discover <a class="header-anchor" href="#discover" aria-label="Permalink to “Discover”">​</a></h3><ul><li>Quien es el usuario que he observado?</li><li>Cuando fue la ultima vez que encontraron este problema?</li><li>Como lo resuelven ahora?</li><li>Cual es la parte mas molesta, lenta o que menos confianza les da?</li></ul><h3 id="define" tabindex="-1">Define <a class="header-anchor" href="#define" aria-label="Permalink to “Define”">​</a></h3><ul><li>De todos estos problemas, cual merece la pena resolver primero?</li><li>Que escenario es el mas frecuente o critico?</li><li>A quien serviremos primero en la primera version, y que problema resolveremos?</li><li>Despues de resolverlo exitosamente, como cambiara el estado del usuario?</li></ul><h3 id="develop" tabindex="-1">Develop <a class="header-anchor" href="#develop" aria-label="Permalink to “Develop”">​</a></h3><ul><li>Para este problema, que soluciones posibles hay?</li><li>Que soluciones son las mas ligeras, rapidas y faciles de verificar?</li><li>Que es imprescindible y que puede esperar?</li></ul><h3 id="deliver" tabindex="-1">Deliver <a class="header-anchor" href="#deliver" aria-label="Permalink to “Deliver”">​</a></h3><ul><li>Cual es lo minimo que podemos entregar para verificar esta direccion?</li><li>Es un diagrama de flujo, un prototipo o un MVP?</li><li>A quien necesitamos pedir que pruebe?</li><li>Despues de la prueba, como decidimos si continuar, modificar o abandonar?</li></ul><h2 id="_9-un-ejemplo-que-incluso-un-principiante-puede-entender" tabindex="-1">9. Un ejemplo que incluso un principiante puede entender <a class="header-anchor" href="#_9-un-ejemplo-que-incluso-un-principiante-puede-entender" aria-label="Permalink to “9. Un ejemplo que incluso un principiante puede entender”">​</a></h2><p>Supongamos que quieres hacer una herramienta de IA para &quot;ayudar a universitarios a preparar su curriculum de busqueda de empleo&quot;.</p><p>Muchas personas entrarian directamente en el segundo diamante, pensando:</p><ul><li>Deberia hacer embellecimiento con un clic?</li><li>Deberia hacer reescritura inteligente?</li><li>Deberia hacer matching automatico con la descripcion del puesto?</li><li>Deberia generar una presentacion personal?</li></ul><p>Pero siguiendo el modelo Double Diamond, un mejor proceso seria:</p><h3 id="primer-diamante" tabindex="-1">Primer diamante <a class="header-anchor" href="#primer-diamante" aria-label="Permalink to “Primer diamante”">​</a></h3><p><strong>Discover</strong></p><ul><li>Hablar con graduados recientes sobre cuando fue la ultima vez que modificaron su curriculum</li><li>Ver como pasan de un curriculum viejo a una nueva version</li><li>Entender si lo que mas les frustra es &quot;no saber escribir&quot;, &quot;no saber modificar&quot; o &quot;no saber juzgar si esta bien&quot;</li></ul><p><strong>Define</strong></p><ul><li>Finalmente converger en un problema mas concreto:</li><li>No es &quot;los universitarios no saben hacer curriculums&quot;</li><li>Sino &quot;los estudiantes que envian su primera candidatura de practica tienen dificultades para reescribir sus experiencias existentes de forma adaptada al puesto, por lo que retrasan el envio&quot;</li></ul><h3 id="segundo-diamante" tabindex="-1">Segundo diamante <a class="header-anchor" href="#segundo-diamante" aria-label="Permalink to “Segundo diamante”">​</a></h3><p><strong>Develop</strong></p><ul><li>Pensar varias soluciones: biblioteca de plantillas, reescritura con IA, comparacion con el puesto, puntuacion del curriculum, referencia de casos</li></ul><p><strong>Deliver</strong></p><ul><li>La primera version solo hace &quot;reescribir los bullet points de experiencias segun la descripcion del puesto&quot;</li><li>Probar con 5 estudiantes, ver si enviaran su primera version mas rapido</li></ul><p>Descubriras que, una vez que el primer diamante se hace solidamente, el segundo diamante se vuelve mucho mas claro.</p><h2 id="_10-resumen" tabindex="-1">10. Resumen <a class="header-anchor" href="#_10-resumen" aria-label="Permalink to “10. Resumen”">​</a></h2><p>Lo mas poderoso del modelo Double Diamond es que te ayuda a descomponer una masa confusa en cuatro acciones mas claras:</p><ul><li>Primero diverge para entender el problema</li><li>Luego converge para definir el problema</li><li>Luego diverge para explorar soluciones</li><li>Finalmente converge para entregar la solucion</li></ul><p>No te hace mas lento, sino que te hace <strong>evitar muchos desvios que parecen ocupados pero van en la direccion equivocada.</strong></p><p>Especialmente en la era de la IA, donde hacer cosas se vuelve cada vez mas rapido, el modelo Double Diamond se vuelve aun mas importante. Porque cuando &quot;hacerlo&quot; es cada vez mas facil, la capacidad verdaderamente escasa se convierte en: <strong>estas resolviendo un problema que vale la pena resolver, y lo estas haciendo de la forma adecuada.</strong></p><p>Recuerda solo esta frase:</p><p><strong>Primero haz lo correcto, luego hazlo bien.</strong></p><p><a id="dd-ai"></a></p><h2 id="_11-como-usar-la-ia-para-recorrer-el-proceso-double-diamond" tabindex="-1"><a href="#top-dd">11. Como usar la IA para recorrer el proceso Double Diamond</a> <a class="header-anchor" href="#_11-como-usar-la-ia-para-recorrer-el-proceso-double-diamond" aria-label="Permalink to “11. Como usar la IA para recorrer el proceso Double Diamond”">​</a></h2><p>El modelo Double Diamond en si no es una herramienta de IA, pero la IA es muy adecuada para actuar como &quot;acelerador&quot; en las cuatro etapas. La clave no es que la IA tome decisiones por ti, sino que te ayude a expandir tu campo de vision, organizar informacion, comparar soluciones y generar materiales de validacion.</p><h3 id="_11-1-en-la-fase-discover-usar-la-ia-para-hacer-una-primera-preparacion-de-informacion" tabindex="-1">11.1 En la fase Discover, usar la IA para hacer una primera preparacion de informacion <a class="header-anchor" href="#_11-1-en-la-fase-discover-usar-la-ia-para-hacer-una-primera-preparacion-de-informacion" aria-label="Permalink to “11.1 En la fase Discover, usar la IA para hacer una primera preparacion de informacion”">​</a></h3><p>Antes de las entrevistas e investigacion formales, puedes pedir a la IA que haga un barrido ligero de problemas, como:</p><ul><li>Que soluciones alternativas comunes existen en el mercado</li><li>De que se quejan mas los usuarios en comunidades publicas</li><li>En que escenarios y grupos de personas es mas frecuente este problema</li><li>Que suelen ignorar los productos existentes</li></ul><p>Este paso no puede sustituir la investigacion real, pero es ideal para construir rapidamente un mapa de problemas.</p><p>Una entrada simple para principiantes podria ser:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Quiero hacer una herramienta para ayudar a universitarios a modificar su curriculum.</span></span>
<span class="line"><span>No me des ideas de funciones todavia, primero ayudame a ver que problemas encuentra mas a menudo la gente con este tema.</span></span></code></pre></div><p>La IA podria responder:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mapa inicial de problemas:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. No saber que experiencias incluir</span></span>
<span class="line"><span>2. No saber como adaptar el curriculum a cada puesto</span></span>
<span class="line"><span>3. Modificar muchas versiones sin certeza de si esta bien</span></span>
<span class="line"><span>4. Necesitar que alguien lo revise, pero no querer molestar siempre</span></span>
<span class="line"><span>5. Por la incertidumbre, posponer continuamente el envio</span></span></code></pre></div><p>La funcion de este tipo de resultado no es sacar conclusiones por ti, sino ayudarte a entrar mas rapido en Discover.</p><h3 id="_11-2-en-la-fase-define-dejar-que-la-ia-te-ayude-a-converger-la-definicion-del-problema" tabindex="-1">11.2 En la fase Define, dejar que la IA te ayude a converger la definicion del problema <a class="header-anchor" href="#_11-2-en-la-fase-define-dejar-que-la-ia-te-ayude-a-converger-la-definicion-del-problema" aria-label="Permalink to “11.2 En la fase Define, dejar que la IA te ayude a converger la definicion del problema”">​</a></h3><p>Despues de recoger mucha informacion, lo mas dificil para mucha gente es comprimir el problema en una frase verdaderamente clara. Puedes pasar tus notas de investigacion a la IA y pedirle que las comprima en varias definiciones de problema candidatas:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>A continuacion estan los comentarios de usuarios y notas de investigacion que he recogido en la fase Discover:</span></span>
<span class="line"><span>[pega el contenido]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Por favor ayudame a hacer tres cosas:</span></span>
<span class="line"><span>1. Identificar los patrones de problemas que aparecen con mas frecuencia</span></span>
<span class="line"><span>2. Organizar 3 problemas que merezca la pena priorizar, segun frecuencia, intensidad de dolor y verificabilidad</span></span>
<span class="line"><span>3. Escribir cada problema como una definicion concreta en una frase</span></span></code></pre></div><p>Asi te sera mas facil entrar en Define, en lugar de quedarte atrapado en &quot;hay muchos problemas&quot;.</p><p>Puedes incluso hacer la entrada muy simple:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Los problemas que he recogido son:</span></span>
<span class="line"><span>1. La gente no sabe que poner en el curriculum</span></span>
<span class="line"><span>2. La gente no sabe como modificarlo</span></span>
<span class="line"><span>3. La gente siempre siente que no esta bien modificado y no se atreve a enviarlo</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Ayudame a ver, cual problema es mas adecuado para resolver primero en la primera version.</span></span></code></pre></div><p>La IA podria responder:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Problema sugerido para priorizar:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&quot;Los estudiantes que envian su primera candidatura de practica no estan seguros de si su curriculum ha alcanzado el nivel necesario para enviar, por lo que lo modifican repetidamente y retrasan el envio.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Razones:</span></span>
<span class="line"><span>1. Este problema es mas concreto</span></span>
<span class="line"><span>2. Puede explicar el comportamiento de procrastinacion</span></span>
<span class="line"><span>3. Es mas facil disenar una version pequena para verificar</span></span></code></pre></div><p>Este tipo de resultado es muy util porque te ayuda a converger de un monton de problemas vagos a una definicion mas como un punto de partida para un MVP.</p><h3 id="_11-3-en-la-fase-develop-usar-la-ia-para-diverger-multiples-soluciones" tabindex="-1">11.3 En la fase Develop, usar la IA para diverger multiples soluciones <a class="header-anchor" href="#_11-3-en-la-fase-develop-usar-la-ia-para-diverger-multiples-soluciones" aria-label="Permalink to “11.3 En la fase Develop, usar la IA para diverger multiples soluciones”">​</a></h3><p>Muchas personas, una vez definido el problema, se fijan solo en la primera solucion que les viene a la mente. La IA es ideal en este paso para forzarte a diverger:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ya he definido un problema central: [tu definicion del problema]</span></span>
<span class="line"><span>Por favor no me des una respuesta final directamente, sino que propongas 2-3 direcciones de solucion desde cada uno de estos angulos:</span></span>
<span class="line"><span>1. El MVP mas ligero</span></span>
<span class="line"><span>2. La solucion mas adecuada para verificar la necesidad</span></span>
<span class="line"><span>3. La solucion mas adecuada para mejorar la experiencia</span></span>
<span class="line"><span>4. Una solucion que no dependa de IA</span></span>
<span class="line"><span>5. Una solucion que dependa de IA</span></span>
<span class="line"><span>Finalmente, compara las ventajas, riesgos y costos de verificacion de cada solucion.</span></span></code></pre></div><p>Asi no te ataras demasiado pronto a una unica solucion.</p><p>Una entrada simple podria ser:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Mi definicion de problema ahora es:</span></span>
<span class="line"><span>&quot;Los universitarios no estan seguros de si su curriculum ya se puede enviar, por lo que siguen posponiendo el envio.&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Por favor ayudame a pensar en 4 soluciones diferentes, no me des solo una.</span></span></code></pre></div><p>La IA podria responder:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Solucion 1: Checklist de &quot;preparacion para enviar&quot; del curriculum</span></span>
<span class="line"><span>Solucion 2: Reescritura adaptada segun la descripcion del puesto</span></span>
<span class="line"><span>Solucion 3: Subir el curriculum y recibir alertas de riesgo</span></span>
<span class="line"><span>Solucion 4: Proporcionar comparacion con casos excelentes para ayudar al usuario a juzgar la distancia</span></span></code></pre></div><p>En este punto te sera mas facil entrar en &quot;comparar soluciones&quot;, en lugar de fijarte solo en la reescritura con IA desde el principio.</p><h3 id="_11-4-en-la-fase-deliver-usar-la-ia-para-generar-textos-de-prototipos-y-materiales-de-prueba" tabindex="-1">11.4 En la fase Deliver, usar la IA para generar textos de prototipos y materiales de prueba <a class="header-anchor" href="#_11-4-en-la-fase-deliver-usar-la-ia-para-generar-textos-de-prototipos-y-materiales-de-prueba" aria-label="Permalink to “11.4 En la fase Deliver, usar la IA para generar textos de prototipos y materiales de prueba”">​</a></h3><p>Cuando entras en la fase Deliver, la IA es muy adecuada para acelerar estos trabajos:</p><ul><li>Generar textos de pagina para prototipos de baja fidelidad</li><li>Organizar un guion de prueba de usuario</li><li>Generar multiples versiones comparables de titulos, botones y descripciones</li><li>Organizar la retroalimentacion y la lista de problemas despues de las pruebas</li></ul><p>Por ejemplo, puedes pedir a la IA que genere un guion de prueba de usuario de 20 minutos, o que te ayude a resumir la retroalimentacion de 5 usuarios en criterios de &quot;continuar / modificar direccion / pausar&quot;.</p><p>Una entrada minima podria ser:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>He hecho un prototipo muy simple:</span></span>
<span class="line"><span>el usuario sube su curriculum y el sistema le indica que partes aun no estan listas para enviar.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Por favor ayudame a generar un guion de prueba de usuario de 15 minutos.</span></span></code></pre></div><p>La IA podria responder:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Guion de prueba de 15 minutos:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. Primero pedir al usuario que describa su ultima experiencia enviando un curriculum</span></span>
<span class="line"><span>2. Dejar que el usuario complete independientemente la subida del curriculum</span></span>
<span class="line"><span>3. Observar si entiende los resultados de la retroalimentacion</span></span>
<span class="line"><span>4. Preguntar: de estas indicaciones, cuales son las mas utiles y cuales te confunden</span></span>
<span class="line"><span>5. Preguntar: antes del proximo envio, te gustaria usar esto de nuevo?</span></span></code></pre></div><p>Este tipo de resultado es muy practico porque te ayuda a pasar de &quot;ya termine el prototipo&quot; a &quot;como lo pruebo ahora&quot;.</p><h3 id="_11-5-dejar-que-la-ia-actue-como-guardian-de-etapas" tabindex="-1">11.5 Dejar que la IA actue como &quot;guardian de etapas&quot; <a class="header-anchor" href="#_11-5-dejar-que-la-ia-actue-como-guardian-de-etapas" aria-label="Permalink to “11.5 Dejar que la IA actue como &quot;guardian de etapas&quot;”">​</a></h3><p>El problema mas comun del modelo Double Diamond es que la gente se salta etapas. Puedes pedir directamente a la IA que actue como guardian, recordandote en que etapa estas realmente:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Por favor actua como coach de proceso de producto.</span></span>
<span class="line"><span>A continuacion esta el estado actual de mi proyecto: [tu descripcion]</span></span>
<span class="line"><span>Por favor juzga en que etapa estoy mas: Discover, Define, Develop o Deliver.</span></span>
<span class="line"><span>Y dime:</span></span>
<span class="line"><span>1. Me he saltado demasiado pronto a la siguiente etapa?</span></span>
<span class="line"><span>2. Cual es la accion mas importante que debo completar en la etapa actual?</span></span>
<span class="line"><span>3. Que cosas no debo hacer ahora?</span></span></code></pre></div><p>Esto es especialmente util para principiantes, porque es facil &quot;empezar a dibujar prototipos antes de haber aclarado el problema&quot;.</p><h2 id="📚-tareas" tabindex="-1">📚 Tareas <a class="header-anchor" href="#📚-tareas" aria-label="Permalink to “📚 Tareas”">​</a></h2><p>Por favor completa las siguientes tareas basandote en el contenido anterior:</p><ol><li>Elige una idea de producto que quieras hacer recientemente, y escribe un borrador de sus cuatro pasos: Discover, Define, Develop, Deliver</li><li>En la fase Define, obligate a comprimir el problema en una frase concreta</li><li>En la fase Develop, lista al menos 3 soluciones diferentes, en lugar de fijarte solo en la primera que se te ocurra</li><li>En la fase Deliver, escribe una version minima de verificacion que puedas entregar en una semana</li></ol><h2 id="lectura-adicional" tabindex="-1">Lectura adicional <a class="header-anchor" href="#lectura-adicional" aria-label="Permalink to “Lectura adicional”">​</a></h2><p>Este articulo se basa principalmente en los materiales oficiales del Design Council sobre el Double Diamond, adecuados para seguir profundizando:</p><ul><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/" target="_blank" rel="noreferrer">Design Council: The Double Diamond</a></li><li><a href="https://www.designcouncil.org.uk/our-work/skills-learning/tools-frameworks/framework-for-innovation-design-councils-evolved-double-diamond/" target="_blank" rel="noreferrer">Design Council: Framework for Innovation</a></li><li><a href="https://www.designcouncil.org.uk/our-resources/the-double-diamond/history-of-the-double-diamond/" target="_blank" rel="noreferrer">Design Council: History of the Double Diamond</a></li></ul>`,171))])}}});export{h as __pageData,g as default};
